void sum(const float* v, size_t lo, size_t hi, double& out) {
    if (hi - lo < 4096) { out = std::accumulate(v + lo, v + hi, 0.0); return; }
    size_t mid = lo + (hi - lo) / 2;
    double l = 0, r = 0;
    tbb::task_group g;
    g.run([&]{ sum(v, lo, mid, l); });        // fork
    g.run([&]{ sum(v, mid, hi, r); });
    g.wait();                                  // join
    out = l + r;
}

